var ms = require('./');

describe('proof', function () {
  it('parses years into milliseconds', function () {
    assert.strictEqual(ms('1y'), 31557600000);
    assert.strictEqual(ms('2y'), 63115200000);
    assert.strictEqual(ms('0.5yr'), 15778800000);
  });
});
"}, "note": "The diff flips year parsing from `n * y` to `n / y`, so any input using the y/yr/year unit is divided by the milliseconds-in-a-year constant instead of multiplied. For example ms('2y') now returns ~6.34e-11 instead of 63115200000."}
```

